 await check('Activity has an internal scroll boundary and new rows preserve the reading position',async()=>{await page.evaluate(()=>{fixtureState.events=Array.from({length:190},(_,index)=>({seq:index,at:Date.now()-index*1000,type:index%3?'request':'recovery-attempt',host:'upos-sz-mirrorcosov.bilivideo.com'}));});await refresh();await show('logs');await page.locator('#log-list li').first().waitFor();const box=page.locator('#log-scroll');await box.evaluate(node=>{node.scrollTop=40;node.dispatchEvent(new Event('scroll'))});const before=await box.evaluate(node=>({top:node.scrollTop,first:node.querySelector('li').textContent}));await page.evaluate(()=>{fixtureState.events.push({seq:191,at:Date.now(),type:'recovery-confirmed'});});await refresh();assert.equal(await box.evaluate(node=>node.scrollTop),before.top);assert.equal(await box.locator('li').first().textContent(),before.first);assert.equal(await page.locator('#follow-logs').isVisible(),true);assert.equal(await box.evaluate(node=>getComputedStyle(node).overflowY),'auto');await page.locator('#follow-logs').click();await page.waitForFunction(()=>document.querySelector('#log-scroll').scrollTop<=1&&document.querySelector('#follow-logs').disabled);assert.equal(await page.locator('#follow-logs').getAttribute('data-has-new'),'false');});
